  // 유틸리티 함수들 (현재 사용하지 않지만 향후 확장을 위해 유지)
  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const extractMainTopics = (text: string): string => {
    const words = text.toLowerCase().split(/\s+/);
    const commonWords = ['이', '그', '저', '것', '수', '등', '및', '또는', '그리고', '하지만', '그러나', '때문에', '위해서', '통해', '통한', '관한', '대한', '있는', '없는', '하는', '되는', '있는', '없는'];
    const filteredWords = words.filter(word => 
      word.length > 1 && !commonWords.includes(word) && !/[0-9]/.test(word)
    );
    
    const wordCount: { [key: string]: number } = {};
    filteredWords.forEach(word => {
      wordCount[word] = (wordCount[word] || 0) + 1;
    });
    
    const sortedWords = Object.entries(wordCount)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 3)
      .map(([word]) => word);
    
    return sortedWords.join(', ');
  };

