  // 대화형 분석 응답 생성 (실시간 지식 시스템 통합)
  const generateConversationalResponse = async (message: string, attachedFiles?: File[]) => {
    try {
      setIsLoading(true);

      // 메시지 길이와 복잡도 분석
      const isLongMessage = message.length > 200;
      const hasMultipleConditions = message.includes('그리고') || message.includes('또한') || message.includes('추가로') || message.includes('먼저') || message.includes('그다음');

      let aiResponseText = '';
      let confidence = 0.5;
      let performance_metrics: {
        processingTime?: number;
        memoryStrength?: number;
        contextContinuity?: number;
        styleConsistency?: number;
      } = {};

      // 대화 기록 변환
      const conversationHistory = messages.map(msg => ({
        id: msg.id,
        content: msg.content,
        sender: msg.isUser ? 'user' : 'ai',
        timestamp: msg.timestamp.toISOString(),
        isUser: msg.isUser,
        type: msg.type || 'text'
      }));

      // 실시간 지식 시스템 사용 (파일이 첨부된 경우 또는 복잡한 요청)
      if (conversationSessionId && (attachedFiles?.length || isLongMessage || hasMultipleConditions || fileProcessedInSession)) {
        try {
          const intelligentResponse = await realTimeKnowledgeSystem.generateIntelligentResponse(
            message,
            selectedProject?.id || 'default',
            conversationSessionId,
            attachedFiles
          );

          aiResponseText = intelligentResponse.response;
          confidence = intelligentResponse.confidence;

          // 성능 지표 매핑
          performance_metrics = {
            processingTime: 1500,
            memoryStrength: confidence,
            contextContinuity: confidence * 0.9,
            styleConsistency: confidence * 0.8
          };

          // 지식 인사이트 추가
          if (intelligentResponse.knowledgeInsights.length > 0) {
            aiResponseText += '\n\n💡 **지식 베이스 인사이트:**\n';
            intelligentResponse.knowledgeInsights.forEach(insight => {
              aiResponseText += `• ${insight}\n`;
            });
          }

          // 후속 질문 추가
          if (intelligentResponse.followUpQuestions.length > 0) {
            aiResponseText += '\n\n🤔 **추가 질문 옵션:**\n';
            intelligentResponse.followUpQuestions.slice(0, 3).forEach(question => {
              aiResponseText += `• ${question}\n`;
            });
          }

          // 제안 액션 추가
          if (intelligentResponse.suggestedActions.length > 0) {
            aiResponseText += '\n\n📋 **제안 액션:**\n';
            intelligentResponse.suggestedActions.slice(0, 3).forEach(action => {
              aiResponseText += `• ${action}\n`;
            });
          }

          // 학습 피드백 표시
          if (intelligentResponse.learningFeedback.newKnowledgeGained) {
            aiResponseText += '\n\n🧠 **새로운 지식이 학습되었습니다!**';
          }

        } catch (error) {
          console.error('실시간 지식 시스템 오류:', error);
          // 기본 시스템으로 폴백
          return generateFallbackResponse(message, conversationHistory, isLongMessage, hasMultipleConditions);
        }

      } else if (isLongMessage || hasMultipleConditions) {
        // 고급 문서 처리 사용 [[memory:5398517]]
        const { advancedDocumentService } = await import('./services/advancedDocumentService');

        const conditions = [];
        if (message.includes('분석')) conditions.push('분석');
        if (message.includes('비교')) conditions.push('비교');
        if (message.includes('제시') || message.includes('제안')) conditions.push('제안');
        if (message.includes('카드뉴스') || message.includes('작성')) conditions.push('작성');

        const contextualResponse = await advancedDocumentService.generateContextualResponse(
          message,
          conversationHistory,
          `ctx_${Date.now()}`
        );

        aiResponseText = contextualResponse.response;
        confidence = contextualResponse.contextStrength;
        performance_metrics = {
          processingTime: 0,
          memoryStrength: contextualResponse.contextStrength,
          contextContinuity: contextualResponse.detailPreservation,
          styleConsistency: contextualResponse.styleMatching
        };

        // 복잡한 요청에 대한 추가 정보 표시
        if (hasMultipleConditions) {
          aiResponseText += '\n\n📋 **복잡한 다중 조건 요청을 체계적으로 처리했습니다.**';
        }

        if (contextualResponse.followUpSuggestions.length > 0) {
          aiResponseText += '\n\n💡 **추가 제안사항:**\n';
          contextualResponse.followUpSuggestions.forEach(suggestion => {
            aiResponseText += `• ${suggestion}\n`;
          });
        }

      } else {
        // 기존 고급 NLP 분석 사용
        const { handleAdvancedChat } = await import('./conversationHandlers/handleAdvancedChat');
        const advancedResponse = await handleAdvancedChat(message, conversationHistory);
        aiResponseText = advancedResponse.response;
        confidence = advancedResponse.confidence;
        performance_metrics = advancedResponse.performance || {};
      }

      const aiMessage = {
        id: Date.now().toString(),
        content: aiResponseText,
        isUser: false,
        timestamp: new Date(),
        type: 'text' as const,
        metadata: {
          confidence: confidence,
          processingTime: performance_metrics.processingTime || 1500,
          modelUsed: isLongMessage || hasMultipleConditions ? 'advanced_document_processor' : 'contextual_analysis',
          analysisType: isLongMessage || hasMultipleConditions ? 'advanced_contextual' : 'contextual',
          responseType: 'conversational',
          memoryStrength: performance_metrics.memoryStrength || 0.5,
          contextContinuity: performance_metrics.contextContinuity || 0.5,
          styleConsistency: performance_metrics.styleConsistency || 0.5,
          isComplexRequest: hasMultipleConditions,
          isLongDocument: isLongMessage
        }
      };

      setTimeout(() => {
        setMessages(prev => [...prev, aiMessage]);
        setIsLoading(false);

        // AI 응답에 TTS 적용
        if (autoTTS) {
          speakAIResponse(aiResponseText);
        }
      }, 1500);

    } catch (error) {
      console.error('문맥 분석 오류:', error);

      const errorMessage = {
        id: Date.now().toString(),
        content: '분석 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.',
        isUser: false,
        timestamp: new Date(),
        type: 'error' as const
      };

      setTimeout(() => {
        setMessages(prev => [...prev, errorMessage]);
        setIsLoading(false);
      }, 1000);
    }
  };

